import{at as e,it as t,n,vt as r}from"./chunks/framework.P6pmeiq0.js";var i=JSON.parse(`{"title":"Relay compared to Kafka","description":"","frontmatter":{},"headers":[],"relativePath":"guide/relay/relay-vs-kafka.md","filePath":"guide/relay/relay-vs-kafka.md","lastUpdated":1792576906000}`),a={name:`guide/relay/relay-vs-kafka.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="relay-compared-to-kafka" tabindex="-1">Relay compared to Kafka <a class="header-anchor" href="#relay-compared-to-kafka" aria-label="Permalink to “Relay compared to Kafka”">​</a></h1><p>The Relay and Kafka both move messages between processes, but they solve different problems. Kafka is a durable, replayable <strong>event log</strong> for data pipelines. The Relay is <strong>live messaging</strong> between the processes of an application, running on the Redis or PostgreSQL you already use for BullMQ.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to “At a glance”">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Kafka</th><th>Relay</th></tr></thead><tbody><tr><td><strong>Model</strong></td><td>An append-only, partitioned log. Consumers pull by offset.</td><td>Live messages, pushed into the inbox of each interested node.</td></tr><tr><td><strong>Who gets a message</strong></td><td>One consumer per consumer group; several groups can each read it.</td><td>Every matching subscription (fan-out). For exactly one consumer, use a BullMQ queue.</td></tr><tr><td><strong>History and replay</strong></td><td>Yes. Messages are kept for a retention period, and can be re-read from any offset.</td><td>No. A subscription only sees what is published after it. <a href="./retained-messages">Retained messages</a> keep the latest value of a topic.</td></tr><tr><td><strong>Durability</strong></td><td>Replicated to disk; survives broker and consumer failures.</td><td>Survives a node&#39;s brief disconnections. A node removed after missing its lease loses its pending messages.</td></tr><tr><td><strong>Topics</strong></td><td>Heavyweight: created up front and partitioned; usually a limited number.</td><td>Free and fine-grained: one per job, user or resource. They only cost anything while someone subscribes.</td></tr><tr><td><strong>Wildcards</strong></td><td>Regex subscriptions to topic names.</td><td>Hierarchical patterns (<code>tenants.acme.&gt;</code>, <code>jobs.*.cancel</code>), resolved by the datastore on every publish.</td></tr><tr><td><strong>Ordering</strong></td><td>Total order per partition (by key).</td><td>Per publisher: messages published one after another arrive in that order.</td></tr><tr><td><strong>Delivery guarantees</strong></td><td>At-least-once by default; exactly-once with idempotent producers and transactions.</td><td>Once per subscription while the node is alive; no replay.</td></tr><tr><td><strong>Throughput</strong></td><td>Very high; scales horizontally with partitions and brokers.</td><td>Bounded by one Redis slot or one PostgreSQL database per namespace: suited to control and notification traffic, not bulk data.</td></tr><tr><td><strong>Infrastructure</strong></td><td>A separate cluster, operated as its own system.</td><td>Nothing beyond what BullMQ already uses.</td></tr><tr><td><strong>Liveness</strong></td><td>Consumer group membership and rebalancing.</td><td>Node leases: dead nodes are removed with their subscriptions.</td></tr></tbody></table><h2 id="how-bullmq-maps-to-kafka-s-concepts" tabindex="-1">How BullMQ maps to Kafka&#39;s concepts <a class="header-anchor" href="#how-bullmq-maps-to-kafka-s-concepts" aria-label="Permalink to “How BullMQ maps to Kafka&#39;s concepts”">​</a></h2><ul><li><strong>Consumer group semantics</strong> (each message processed once, with retries) are BullMQ <strong>queues</strong>, which also offer delays, priorities, per-job retries with backoff, rate limits and flows.</li><li><strong>Fan-out to live processes</strong> is the <strong>Relay</strong>.</li><li><strong>A compacted topic</strong> (the latest value per key) is roughly a <strong>retained message</strong>, kept per topic and for a limited time.</li><li><strong>A replayable log</strong> has no equivalent, by design: when a message must be processed reliably, put it in a queue.</li></ul><h2 id="when-to-use-which" tabindex="-1">When to use which <a class="header-anchor" href="#when-to-use-which" aria-label="Permalink to “When to use which”">​</a></h2><p><strong>Kafka</strong>: event sourcing, analytics and ETL pipelines, change data capture, many independent consumers that must each process the full history, very high volumes.</p><p><strong>The Relay</strong>: signals between the processes of your application: cancel this job, show this progress, invalidate this cache entry, apply this configuration, notify this user. These messages are small, targeted and only useful now. Kafka would be heavy for them: per-job topics aren&#39;t practical, it is one more cluster to operate, and replaying old signals has no use.</p><p>They also work well together: Kafka for the data pipeline, BullMQ queues for the work, and the Relay to keep the live parts of the application in sync.</p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};